-- composition of rule kernels GroupByOrder x QueryFlattener (sqlite), template cte_twice
WITH ka AS (SELECT '1999-12-31 23:59:59.999' AS c0, CAST(1.5 AS NUMERIC) AS c1, CAST(1000 AS INTEGER) AS c2 FROM (SELECT TRUE AS c0, 11 AS c1 FROM t0 AS a1) AS a2), kb AS (WITH cte1 AS (SELECT DISTINCT 7 AS c0 FROM tp AS a1 ORDER BY 1) SELECT CAST('ß' AS TEXT) AS c0, CAST(10.0 AS REAL) AS c1, '{"k": -1, "a": [1, 2, 3]}' AS c2 UNION SELECT a2.c1 AS c0, CASE WHEN FALSE THEN CAST(10.0 AS REAL) ELSE CAST(1.0 AS REAL) END AS c1, (SELECT JSON_GROUP_ARRAY (7 ORDER BY 7) FROM cte1 AS a3 WHERE FALSE) AS c2 FROM tl AS a2 WHERE ('{"k": 1, "a": [1, 2]}' = '{}')) SELECT (SELECT count(*) FROM ka) + (SELECT count(*) FROM kb) + (SELECT count(*) FROM ka);
